import Foundation

/// In-memory clipboard history and the separate FIFO/FILO paste queue.
///
/// Policy:
/// - A real user copy is recorded in history (newest first) unless it is empty,
///   not text, marked internal, or carries a concealed / transient / auto-generated
///   pasteboard type. Consecutive identical history heads collapse into one row.
/// - In FIFO or FILO mode that same copy is also appended to the queue. The queue
///   keeps duplicates on purpose, so the same snippet can be pasted twice. Queue
///   items are distinct values from history items.
/// - Advancing the queue removes only the staged queue item. It does not insert,
///   delete, or reorder history.
/// - Internal writes (staging the next queue item, or copying a history row back
///   to the pasteboard) are ignored, so putting the next item on the clipboard
///   cannot create a new history row.
///
/// The queue is oldest-first. FIFO stages `queue.first`. FILO stages `queue.last`.
/// Not thread-safe; the app uses it on the main thread.
public struct ClipboardStore: Equatable, Sendable {
    public static let defaultMaxHistory = 50
    public static let minimumMaxHistory = 1
    /// Marker placed on pasteboard items this app writes. Watchers must ignore them
    /// so queue advancement does not look like a user copy.
    public static let internalTypeIdentifier = "app.clipkyu.internal-write"
    public static let sensitiveTypeIdentifiers: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    public private(set) var mode: ClipMode
    public private(set) var maxHistory: Int
    /// Newest first.
    public private(set) var history: [ClipItem]
    /// Oldest first.
    public private(set) var queue: [ClipItem]
    /// Queue item currently prepared as the next paste. Nil in normal mode and when the queue is empty.
    public private(set) var stagedID: UUID?

    public init(
        mode: ClipMode = .normal,
        maxHistory: Int = ClipboardStore.defaultMaxHistory,
        history: [ClipItem] = [],
        queue: [ClipItem] = [],
        stagedID: UUID? = nil
    ) {
        self.mode = mode
        self.maxHistory = max(Self.minimumMaxHistory, maxHistory)
        self.history = history
        self.queue = queue
        self.stagedID = stagedID
        trimHistory()
        if let stagedID, !self.queue.contains(where: { $0.id == stagedID }) {
            self.stagedID = nil
        }
    }

    public static func isSensitive(types: [String]) -> Bool {
        types.contains { sensitiveTypeIdentifiers.contains($0) }
    }

    public func historyItem(id: UUID) -> ClipItem? {
        history.first { $0.id == id }
    }

    public func stagedItem() -> ClipItem? {
        guard let stagedID else { return nil }
        return queue.first { $0.id == stagedID }
    }

    /// Records a user copy. `now` is the timestamp stored on new items.
    public mutating func ingest(_ snapshot: PasteboardSnapshot, now: Date = Date()) -> IngestResult {
        if snapshot.types.contains(Self.internalTypeIdentifier) {
            return IngestResult(skip: .internalWrite, historyInserted: false, enqueued: false, stage: nil)
        }
        if Self.isSensitive(types: snapshot.types) {
            return IngestResult(skip: .sensitive, historyInserted: false, enqueued: false, stage: nil)
        }
        guard let text = snapshot.text else {
            return IngestResult(skip: .notText, historyInserted: false, enqueued: false, stage: nil)
        }
        if text.isEmpty {
            return IngestResult(skip: .empty, historyInserted: false, enqueued: false, stage: nil)
        }

        var historyInserted = false
        if history.first?.text != text {
            history.insert(ClipItem(id: UUID(), text: text, createdAt: now), at: 0)
            trimHistory()
            historyInserted = true
        }

        guard mode == .fifo || mode == .filo else {
            return IngestResult(skip: nil, historyInserted: historyInserted, enqueued: false, stage: nil)
        }

        queue.append(ClipItem(id: UUID(), text: text, createdAt: now))
        let stageItem = (mode == .fifo) ? queue.first : queue.last
        stagedID = stageItem?.id
        return IngestResult(skip: nil, historyInserted: historyInserted, enqueued: true, stage: stageItem)
    }

    /// Removes the queue item that was pasted and stages the next one.
    /// `pastedID` is the item staged at key-down. When nil, the current stage is used.
    /// Returns the item to place on the pasteboard, or nil when the queue is exhausted
    /// (the clipboard should keep the text that was just pasted). History is not modified.
    @discardableResult
    public mutating func advanceAfterPaste(of pastedID: UUID? = nil) -> ClipItem? {
        guard mode == .fifo || mode == .filo else { return nil }
        guard let current = pastedID ?? stagedID else { return nil }
        if let index = queue.firstIndex(where: { $0.id == current }) {
            queue.remove(at: index)
        }
        return restage()
    }

    /// Points `stagedID` at the item that should be pasted next for the current mode.
    /// Normal mode clears the stage and leaves the queue in place.
    @discardableResult
    public mutating func restage() -> ClipItem? {
        switch mode {
        case .normal:
            stagedID = nil
            return nil
        case .fifo:
            stagedID = queue.first?.id
            return queue.first
        case .filo:
            stagedID = queue.last?.id
            return queue.last
        }
    }

    @discardableResult
    public mutating func setMode(_ mode: ClipMode) -> ClipItem? {
        self.mode = mode
        return restage()
    }

    public mutating func clearQueue() {
        queue.removeAll()
        stagedID = nil
    }

    public mutating func setMaxHistory(_ maxHistory: Int) {
        self.maxHistory = max(Self.minimumMaxHistory, maxHistory)
        trimHistory()
    }

    private mutating func trimHistory() {
        if history.count > maxHistory {
            history.removeLast(history.count - maxHistory)
        }
    }
}
